from rules import candidates


def solve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = data.get('features', [])
    names = sorted(packages)
    best_score = None
    best_versions = None

    constraints = {name: [tuple(bounds)] for name, bounds in roots.items()}

    def is_acyclic(graph):
        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            for dependency in graph.get(name, []):
                if not visit(dependency):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in graph)

    def search(versions, active_constraints, graph):
        nonlocal best_score, best_versions

        for name, bounds_list in active_constraints.items():
            if name in versions and any(
                not (low <= versions[name] <= high)
                for low, high in bounds_list
            ):
                return

        pending = [name for name in active_constraints if name not in versions]
        if not pending:
            score = tuple(versions.get(name, -1) for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = dict(versions)
            return

        name = min(pending)
        if name not in packages:
            return

        rows = candidates(packages[name], active_constraints[name])
        forbidden = blocked.get(name, [])
        if name in pins:
            rows = [row for row in rows if row['version'] == pins[name]]
        rows = [row for row in rows if row['version'] not in forbidden]

        for row in rows:
            next_versions = dict(versions)
            next_versions[name] = row['version']
            next_constraints = {
                key: list(value) for key, value in active_constraints.items()
            }
            next_graph = {key: list(value) for key, value in graph.items()}
            active_dependencies = []
            valid = True

            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                dep_name = dep['name']
                interval = (dep['min'], dep['max'])
                active_dependencies.append(dep_name)
                next_constraints.setdefault(dep_name, []).append(interval)
                if dep_name in next_versions and not (
                    interval[0] <= next_versions[dep_name] <= interval[1]
                ):
                    valid = False
                    break

            if not valid:
                continue
            next_graph[name] = active_dependencies
            if is_acyclic(next_graph):
                search(next_versions, next_constraints, next_graph)

    search({}, constraints, {})
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

def candidates(rows, bounds=None):
    if bounds is None:
        eligible = list(rows)
    else:
        if len(bounds) == 2 and all(isinstance(value, int) for value in bounds):
            intervals = [bounds]
        else:
            intervals = bounds
        eligible = [
            row for row in rows
            if all(low <= row['version'] <= high for low, high in intervals)
        ]
    return sorted(eligible, key=lambda row: row['version'], reverse=True)
